#!/usr/bin/env node
'use strict';

/**
 * Verify every "learn more" URL in a deck resolves.
 *
 * Cards are frequently generated by a model, and a plausible-looking URL that
 * 404s is worse than no link at all — it spends the reader's click and their
 * trust. Run this after any /thinking-deck generation.
 *
 *   node bin/checklinks.js [path-to-deck.json]
 */

const path = require('path');
const paths = require('../lib/paths');
const { readJson } = require('../lib/jsonio');

const CONCURRENCY = 8;
const TIMEOUT_MS = 15000;

/**
 * Hosts that rate-limit, and how long to wait between hits.
 *
 * The checker reported HTTP 429 on a batch of perfectly good PubMed links,
 * because eight workers hitting NCBI at once exceeds the roughly three
 * requests a second they allow without an API key. A checker that invents
 * failures is worse than no checker, so these hosts get a single-file queue.
 */
const THROTTLED = [{ match: /ncbi\.nlm\.nih\.gov$/, gapMs: 800 }];
const lastHit = new Map();

function throttleFor(url) {
  try {
    const host = new URL(url).hostname;
    return THROTTLED.find((t) => t.match.test(host)) || null;
  } catch { return null; }
}

async function waitTurn(url) {
  const rule = throttleFor(url);
  if (!rule) return;
  const key = rule.match.source;
  const prev = lastHit.get(key) || 0;
  const wait = Math.max(0, prev + rule.gapMs - Date.now());
  lastHit.set(key, Date.now() + wait);
  if (wait > 0) await new Promise((r) => setTimeout(r, wait));
}

async function check(url) {
  await waitTurn(url);
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), TIMEOUT_MS);
  try {
    const res = await fetch(url, {
      redirect: 'follow',
      signal: ac.signal,
      // Some hosts reject unknown agents outright; a browser-ish UA keeps the
      // check from reporting false failures on links that work fine for humans.
      headers: { 'user-agent': 'Mozilla/5.0 (compatible; smart-thinking-linkcheck/0.1)' },
    });
    if (res.status === 429) {
      // Back off and try once more; reporting this as a dead link would be a
      // false failure caused by the checker's own request rate.
      await new Promise((r) => setTimeout(r, 5000));
      // The retry goes through the same queue, or it just re-triggers the limit.
      await waitTurn(url);
      const retry = await fetch(url, {
        redirect: 'follow',
        headers: { 'user-agent': 'Mozilla/5.0 (compatible; smart-thinking-linkcheck/0.1)' },
      });
      return retry.ok ? null : `HTTP ${retry.status} (after retry)`;
    }
    return res.ok ? null : `HTTP ${res.status}`;
  } catch (err) {
    return `ERR ${err.message}`;
  } finally {
    clearTimeout(timer);
  }
}

async function main() {
  const file = process.argv[2]
    || (readJson(paths.deckFile, null) ? paths.deckFile : path.join(__dirname, '..', 'data', 'deck.sample.json'));

  const deck = readJson(file, null);
  if (!deck || !Array.isArray(deck.cards)) {
    console.error(`no deck found at ${file}`);
    process.exit(2);
  }

  console.log(`checking ${deck.cards.length} cards in ${file}`);

  const noUrl = deck.cards.filter((c) => !c.url);
  const queue = deck.cards.filter((c) => c.url).slice();
  const failures = [];

  await Promise.all(Array.from({ length: CONCURRENCY }, async () => {
    while (queue.length) {
      const card = queue.shift();
      const problem = await check(card.url);
      if (problem) failures.push({ id: card.id, url: card.url, problem });
    }
  }));

  if (noUrl.length) {
    console.log(`\n${noUrl.length} card(s) with no url:`);
    for (const c of noUrl) console.log(`  ${c.id}`);
  }

  if (failures.length === 0) {
    console.log(`\nall ${deck.cards.length - noUrl.length} links OK`);
    return;
  }

  console.log(`\n${failures.length} broken link(s):`);
  for (const f of failures) console.log(`  ${f.id}  ${f.problem}\n    ${f.url}`);
  process.exitCode = 1;
}

main();
